#!/usr/bin/env bash
set -euo pipefail

CONTAINER_NAME="sap-npl-lowram"
IMAGE_NAME="yoraco/sap-dev-edition-7.52-sp04:latest"
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

echo "======================================================================"
echo " MINI-SAP 7.52 SP04 (Sybase ASE) - LOW-RAM (< 3 GB) LAUNCHER"
echo "======================================================================"

# 1. Ensure the Low-RAM profile and installer script are generated by mini-sap-rs
"${SCRIPT_DIR}/mini-sap-rs" PATCH_NPL
chmod +x "${SCRIPT_DIR}/sap_kernel_bins/install-lowram.sh"

# 2. Check if the container already exists
if docker ps -a --format '{{.Names}}' | grep -qx "${CONTAINER_NAME}"; then
    echo "[INFO] Container '${CONTAINER_NAME}' already exists. Starting..."
    docker start "${CONTAINER_NAME}"
    if docker exec "${CONTAINER_NAME}" test -f /tmp/sapdownloads/installed; then
        docker exec "${CONTAINER_NAME}" bash -c "/usr/sbin/uuidd || true; su - npladm -c 'startsap ALL'"
    else
        echo "[INFO] Resuming Low-RAM installation inside the container..."
        docker exec "${CONTAINER_NAME}" bash -c "/usr/sbin/uuidd || true; cd /tmp/sapdownloads && bash /tmp/sapdownloads/install-lowram.sh -k"
    fi
else
    echo "[INFO] Creating container '${CONTAINER_NAME}' with --shm-size=4g, 6g RAM cap, and ports 3200/3300/8000/44300..."
    docker run -d \
        --name "${CONTAINER_NAME}" \
        -h vhcalnplci \
        --shm-size="4g" \
        --memory="6g" \
        --memory-swap="8g" \
        -p 3200:3200 \
        -p 3300:3300 \
        -p 8000:8000 \
        -p 44300:44300 \
        -v "${SCRIPT_DIR}/sap_kernel_bins/install-lowram.sh:/tmp/sapdownloads/install-lowram.sh:ro" \
        -v "${SCRIPT_DIR}/sap_kernel_bins/sapmnt/NPL/profile/NPL_D00_vhcalnplci.lowram:/tmp/sapdownloads/NPL_D00_vhcalnplci.lowram:ro" \
        "${IMAGE_NAME}" \
        tail -f /dev/null

    echo "[INFO] Container started. Starting uuidd and running Low-RAM installer (/tmp/sapdownloads/install-lowram.sh -k)..."
    docker exec "${CONTAINER_NAME}" bash -c "/usr/sbin/uuidd || true; cd /tmp/sapdownloads && bash /tmp/sapdownloads/install-lowram.sh -k"
fi

echo ""
echo "======================================================================"
echo " Ready! Connect with SAP GUI for Java (127.0.0.1:3200, Instance 00):"
echo "   Client: 001 | User: DEVELOPER | Password: Down1oad"
echo "   (or Client: 000 | User: SAP* | Password: Down1oad for SLICENSE)"
echo "======================================================================"
